# ============================================================================
# INITIALIZATION
# ============================================================================

def start_tel_device(config, _logger, onstepx=None):
    """Initialize telescope device with shared OnStepX connection.

    Args:
        config: Configuration object
        _logger: Logger instance
        onstepx: Shared OnStepXDevice instance (created by app.py)
    """
    global logger, device
    logger = _logger
    device = TelescopeDevice(logger, config, onstepx)
    logger.info('Telescope device initialized')
